#include "FullDiveModeDegradationManager.h"
namespace dnxr { FullDiveModeDecision FullDiveModeDegradationManager::evaluate(const FullDiveModalityReadiness& r) const { FullDiveModeDecision d; if(r.emergency){d.mode=FullDiveRuntimeMode::EmergencyDecompressionOnly; d.auditReason="emergency_decompression"; return d;} bool all=true; for(std::size_t i=0;i<r.supported.size();++i) all = all && r.supported[i] && r.calibrated[i] && r.feedback[i]; if(all){d.mode=FullDiveRuntimeMode::FullFiveSenseClosedLoop; d.fullDiveClaimAllowed=true; d.auditReason="all_modalities_supported_calibrated_feedbacked"; return d;} if(r.supported[0]&&r.supported[1]&&r.calibrated[0]&&r.calibrated[1]){d.mode=r.supported[2]?FullDiveRuntimeMode::XRHapticNonInvasive:FullDiveRuntimeMode::VisualAudioOnly; d.auditReason="partial_modalities_only"; return d;} d.mode=r.simulationOnly?FullDiveRuntimeMode::SimulationOnly:FullDiveRuntimeMode::NoHumanMode; d.auditReason="insufficient_modality_readiness"; return d; } }
